"""Stable runtime API surface for Kestrel kernels.

This module provides a single place for kernel entrypoints used by Kestrel.
Callers should depend on this API rather than deep internal module paths.
"""


import sys
import threading
import weakref
from dataclasses import dataclass, field
from typing import Any, Callable, Sequence

import torch


from kestrel_kernels.flash_attn.cute.mask_ids import (
    BLOCK_BIDIRECTIONAL_MASK_ID as _BLOCK_BIDIRECTIONAL_HASH,
    WINDOWED_BLOCKDIAG_MASK_ID as _WINDOWED_BLOCKDIAG_HASH,
)


_PACKED_PREFILL_TOPOLOGY_SEAL = object()


class PackedPrefillTopologyToken:
    """Fieldless capability for one factory-owned packed-offset topology."""

    __slots__ = ("__weakref__",)

    def __new__(cls, *, _seal: object | None = None):
        if _seal is not _PACKED_PREFILL_TOPOLOGY_SEAL:
            raise ValueError("packed prefill topology tokens are factory-owned")
        return super().__new__(cls)


@dataclass(frozen=True, slots=True)
class _PackedPrefillTopologyRecord:
    working_tensor: Any = field(repr=False, compare=False)
    canonical_tensor: Any = field(repr=False, compare=False)
    data_ptr: int
    version: int
    canonical_data_ptr: int
    canonical_version: int
    device: str
    dtype: Any = field(repr=False)
    shape: tuple[int, ...]
    sequence_lengths: tuple[int, ...]
    host_offsets: tuple[int, ...]
    ready_event: Any = field(repr=False, compare=False, default=None)


@dataclass(frozen=True, slots=True)
class _PackedPrefillTopologyAuthority:
    canonical_tensor: Any = field(repr=False, compare=False)
    sequence_lengths: tuple[int, ...]
    host_offsets: tuple[int, ...]
    ready_event: Any = field(repr=False, compare=False, default=None)


_PACKED_PREFILL_TOPOLOGY_LOCK = threading.RLock()
_PACKED_PREFILL_TOPOLOGY_RECORDS: weakref.WeakKeyDictionary[
    PackedPrefillTopologyToken, _PackedPrefillTopologyRecord
] = weakref.WeakKeyDictionary()


def _packed_sequence_lengths(value: Sequence[int]) -> tuple[int, ...]:
    if isinstance(value, (str, bytes)):
        raise ValueError(
            "sequence_lengths must be a nonempty sequence of nonnegative integers"
        )
    result = tuple(value)
    if not result or any(
        type(length) is not int or length < 0
        for length in result
    ):
        raise ValueError(
            "sequence_lengths must be a nonempty sequence of nonnegative integers"
        )
    return result


def _tensor_binding(tensor: Any) -> tuple[int, int, str, Any, tuple[int, ...]]:
    try:
        return (
            int(tensor.data_ptr()),
            int(tensor._version),
            str(tensor.device),
            tensor.dtype,
            tuple(int(dimension) for dimension in tensor.shape),
        )
    except (AttributeError, TypeError, ValueError) as exc:
        raise ValueError("packed prefill offset tensor metadata is unavailable") from exc


def bind_packed_prefill_topology(
    *,
    sequence_lengths: Sequence[int],
    device: torch.device | str,
) -> tuple[torch.Tensor, PackedPrefillTopologyToken]:
    """Construct exact device offsets and seal their ordered host topology.

    The factory owns both offset derivation and device allocation. A caller cannot
    attach authority to independently populated offsets with the same count/total.
    """

    lengths = _packed_sequence_lengths(sequence_lengths)
    expected_offsets = [0]
    for length in lengths:
        offset = expected_offsets[-1] + length
        if offset > 2_147_483_647:
            raise ValueError(
                "packed prefill offsets must fit the positive int32 domain"
            )
        expected_offsets.append(offset)
    destination_device = torch.device(device)
    if destination_device.type not in {"cuda", "mps"}:
        raise ValueError("packed prefill topology requires a CUDA or MPS device")
    # Qwen builds packed prefill batches under ``torch.inference_mode``. Tensors
    # allocated directly in that context have no version counter, but the
    # topology capability uses the counter to reject in-place mutation without
    # synchronizing to read device offsets. Allocate both private tensors as
    # ordinary versioned tensors even when the caller is in inference mode.
    with torch.inference_mode(False):
        canonical_offsets = torch.tensor(
            expected_offsets,
            dtype=torch.int32,
            device=destination_device,
        )
        cu_seqlens = canonical_offsets.clone()
    ready_event = None
    if isinstance(canonical_offsets, torch.Tensor) and canonical_offsets.is_cuda:
        ready_event = torch.cuda.Event(blocking=False, interprocess=False)
        ready_event.record(torch.cuda.current_stream(canonical_offsets.device))
    if (
        cu_seqlens.dtype != torch.int32
        or cu_seqlens.ndim != 1
        or not cu_seqlens.is_contiguous()
        or int(cu_seqlens.numel()) != len(expected_offsets)
    ):
        raise ValueError(
            "cu_seqlens must be one contiguous device int32 element per host offset"
        )
    data_ptr, version, device, dtype, shape = _tensor_binding(cu_seqlens)
    canonical_data_ptr, canonical_version, canonical_device, canonical_dtype, canonical_shape = (
        _tensor_binding(canonical_offsets)
    )
    if (
        canonical_data_ptr == data_ptr
        or canonical_device != device
        or canonical_dtype != dtype
        or canonical_shape != shape
    ):
        raise ValueError("packed prefill canonical offsets are not privately allocated")
    token = PackedPrefillTopologyToken(_seal=_PACKED_PREFILL_TOPOLOGY_SEAL)
    record = _PackedPrefillTopologyRecord(
        working_tensor=cu_seqlens,
        canonical_tensor=canonical_offsets,
        data_ptr=data_ptr,
        version=version,
        canonical_data_ptr=canonical_data_ptr,
        canonical_version=canonical_version,
        device=device,
        dtype=dtype,
        shape=shape,
        sequence_lengths=lengths,
        host_offsets=tuple(expected_offsets),
        ready_event=ready_event,
    )
    with _PACKED_PREFILL_TOPOLOGY_LOCK:
        _PACKED_PREFILL_TOPOLOGY_RECORDS[token] = record
    return cu_seqlens, token


def _resolve_packed_prefill_topology_authority(
    token: PackedPrefillTopologyToken | None,
    cu_seqlens: Any,
    sequence_lengths: Sequence[int] | None,
) -> _PackedPrefillTopologyAuthority | None:
    """Resolve one immutable canonical tensor plus its sealed host geometry."""

    if sequence_lengths is None or not isinstance(
        token,
        PackedPrefillTopologyToken,
    ):
        return None
    try:
        lengths = _packed_sequence_lengths(sequence_lengths)
    except (TypeError, ValueError):
        return None
    with _PACKED_PREFILL_TOPOLOGY_LOCK:
        record = _PACKED_PREFILL_TOPOLOGY_RECORDS.get(token)
        if record is None:
            return None
        try:
            working_binding = _tensor_binding(cu_seqlens)
            canonical_binding = _tensor_binding(record.canonical_tensor)
        except ValueError:
            return None
        expected_working_binding = (
            record.data_ptr,
            record.version,
            record.device,
            record.dtype,
            record.shape,
        )
        expected_canonical_binding = (
            record.canonical_data_ptr,
            record.canonical_version,
            record.device,
            record.dtype,
            record.shape,
        )
        expected_offsets = [0]
        for length in record.sequence_lengths:
            expected_offsets.append(expected_offsets[-1] + length)
        if (
            record.working_tensor is not cu_seqlens
            or record.sequence_lengths != lengths
            or working_binding != expected_working_binding
            or canonical_binding != expected_canonical_binding
            or record.host_offsets != tuple(expected_offsets)
        ):
            return None
        return _PackedPrefillTopologyAuthority(
            canonical_tensor=record.canonical_tensor,
            sequence_lengths=record.sequence_lengths,
            host_offsets=record.host_offsets,
            ready_event=record.ready_event,
        )


def _resolve_packed_prefill_topology_offsets(
    token: PackedPrefillTopologyToken | None,
    cu_seqlens: Any,
    sequence_lengths: Sequence[int] | None,
    *,
    num_sequences: int,
    total_tokens: int,
) -> tuple[Any, _PackedPrefillTopologyAuthority | None]:
    """Resolve supplied topology authority or reject it before backend routing."""

    has_token = token is not None
    has_lengths = sequence_lengths is not None
    if not has_token and not has_lengths:
        return cu_seqlens, None
    if has_token != has_lengths:
        raise ValueError(
            "packed prefill topology requires both sequence_lengths and its token"
        )
    authority = _resolve_packed_prefill_topology_authority(
        token,
        cu_seqlens,
        sequence_lengths,
    )
    if (
        authority is None
        or len(authority.sequence_lengths) != num_sequences
        or authority.host_offsets[-1] != total_tokens
    ):
        raise ValueError(
            "packed prefill topology authority does not match the active batch"
        )
    return authority.canonical_tensor, authority


def _prepare_packed_prefill_topology_launch(
    authority: _PackedPrefillTopologyAuthority,
    stream_tensor: Any,
) -> Any:
    """Make one private canonical-offset tensor safe for a raw async launch."""

    canonical_tensor = authority.canonical_tensor
    if not isinstance(stream_tensor, torch.Tensor) or not stream_tensor.is_cuda:
        return canonical_tensor
    if (
        not isinstance(canonical_tensor, torch.Tensor)
        or not canonical_tensor.is_cuda
        or authority.ready_event is None
        or canonical_tensor.device != stream_tensor.device
    ):
        raise RuntimeError(
            "packed prefill topology lacks exact CUDA launch-lifetime authority"
        )
    launch_stream = torch.cuda.current_stream(stream_tensor.device)
    launch_stream.wait_event(authority.ready_event)
    canonical_tensor.record_stream(launch_stream)
    return canonical_tensor


def _missing_runtime_fn(domain: str, name: str, exc: Exception) -> Callable[..., Any]:
    def _missing(*_args, **_kwargs):
        raise RuntimeError(
            f"kestrel-kernels: '{domain}.{name}' is unavailable on this platform/runtime. "
            f"Original import error: {type(exc).__name__}: {exc}"
        ) from exc

    return _missing


def _missing_mask(cute_hash: str) -> Callable[..., Any]:
    def _mask(*_args, **_kwargs):
        raise RuntimeError(
            "kestrel-kernels: this flash-attention mask_mod requires the CuTe "
            "flash-attention runtime (the '[jit]' dependency group). The stub only "
            "carries __cute_hash__ for dispatch-by-hash to the shipped cubin."
        )

    _mask.__cute_hash__ = cute_hash
    return _mask


def _topk_torch_fwd(
    x: torch.Tensor,
    k: int,
    softmax: bool = False,
) -> tuple[torch.Tensor, torch.Tensor]:
    values, indices = torch.topk(x, k=k, dim=-1)
    if softmax:
        values = torch.softmax(values.float(), dim=-1).to(x.dtype)
    return values, indices.to(torch.int32)


def _moe_topk_fwd(
    cuda_topk_fwd: Callable[..., Any],
) -> Callable[..., tuple[torch.Tensor, torch.Tensor]]:
    def _topk_fwd(
        x: torch.Tensor,
        k: int,
        softmax: bool = False,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        if (
            x.is_cuda
            and x.dtype == torch.bfloat16
            and x.ndim == 2
            and x.is_contiguous()
            and x.size(1) in (64, 256)
            and k == 8
            and softmax
        ):
            return cuda_topk_fwd(x, k, softmax=softmax)
        return _topk_torch_fwd(x, k, softmax=softmax)

    return _topk_fwd


def _cuda_moe_supports_lora(device: torch.device | str | None = None) -> bool:
    if device is None:
        if not torch.cuda.is_available():
            return False
        device = torch.device("cuda", torch.cuda.current_device())
    else:
        device = torch.device(device)
    if device.type != "cuda":
        return False
    if not torch.cuda.is_available():
        return False

    try:
        from kestrel_kernels.moe.lora.cute import supports_moe_lora
    except Exception:
        return False
    return supports_moe_lora(device)


