@dataclass(frozen=True)
class DenseRuntime:
    # High-level cross-arch API — handles shape validation, 3D→2D
    # reshape, and variant selection. Each backend
    # (CUDA, MPS, …) supplies its own implementation under the same
    # name. Compare ``RotaryRuntime.rotary_embedding`` /
    # ``TauRuntime.tau_tail_apply_into`` — arch-neutral fields that work
    # cross-arch without ``is_cuda`` gates at the call site.
    fused_mlp_gelu_bias_residual: Callable[..., Any]
    # ``mlp_gelu_bias_residual(x, w1, b1, w2, b2, residual, *, approximate)``
    # owns backend selection and temporary workspace allocation.
    mlp_gelu_bias_residual: Callable[..., Any]
    # ``layernorm_bias_into(out, x, weight, bias, eps, *, variant="auto") -> None``
    layernorm_bias_into: Callable[..., Any]
    # ``layernorm_bias(x, weight, bias, *, eps=1e-5) -> Tensor``
    layernorm_bias: Callable[..., Any]
    # ``rmsnorm_into(out, x, weight, eps) -> None``
    rmsnorm_into: Callable[..., Any]
    # ``rmsnorm(x, weight, eps) -> Tensor``
    rmsnorm: Callable[..., Any]
    # ``add_rmsnorm_into(out, residual, x, weight, eps) -> None``
    add_rmsnorm_into: Callable[..., Any]
    # ``add_rmsnorm(residual, x, weight, eps) -> Tensor``; mutates residual.
    add_rmsnorm: Callable[..., Any]
    # ``gated_activation_into(out, gate_up, *, activation, layout) -> None``
    gated_activation_into: Callable[..., Any]


@dataclass(frozen=True)
class SamplingRuntime:
    """Sampling entry points published by every backend.

    ``(logits, temperatures, top_p, *, out=None, generator=None,
      require_packed=False)
      -> token_ids[B]``

    CUDA: clamp + softmax + cubin top_p sampler (existing chain).
    MPS:  one fused Metal dispatch — temperature scale + online
          softmax + top-K + top-p truncate + exp-race sample.
    CPU / other: torch reference.

    ``apply_logits_constraints_`` applies the same range/partition plan
    contract on every device. CUDA may require its packed cubin; other
    backends either provide their native implementation or fail that strict
    requirement explicitly.
    ``constrained_argmax_from_logits`` applies the same range/partition plan
    contract on every device. ``greedy_tail_from_logits`` publishes both the
    selected IDs and indexed pending-token state; its workspace is allocated
    once with ``allocate_greedy_tail_workspace``. CUDA may require packed
    cubins; other backends preserve the same semantics with torch operations.
    """

    sample_step_from_logits: Callable[..., Any]
    greedy_logprobs_from_logits: Callable[..., Any]
    apply_logits_constraints_: Callable[..., Any]
    constrained_argmax_from_logits: Callable[..., Any]
    greedy_tail_from_logits: Callable[..., Any]
    allocate_greedy_tail_workspace: Callable[..., Any]


class KernelRuntime:
    """Unified kernel runtime view used by Kestrel."""

    def __init__(self) -> None:
        # Provider construction may import optional modules. Finish it before
        # callers enter torch.compile so `.attention` is a pure field read.
        self._attention = self._build_attention_runtime()

    @property
    def attention(self) -> AttentionRuntime:
        return self._attention

    def _build_attention_runtime(self) -> AttentionRuntime:
        # `interface._flash_attn_fwd` is cutlass-free (dispatch goes through
        # shipped cubins). `mask_definitions.cute_block_bidirectional_mask` is
        # the real cute.jit mask, but importing it requires cutlass — wheel
        # installs without the `jit` dependency-group fall back to a stub
        # callable that carries the same `__cute_hash__`, so dispatch-by-hash
        # still picks the matching cubin variant without ever invoking
        # the mask.
        try:
            from kestrel_kernels.arch import get_cuda_device_name_key
            from kestrel_kernels.flash_attn.cute.interface import (
                _flash_attn_fwd,
                initialize_attention_backend_selection,
            )
            if torch.cuda.is_available():
                initialize_attention_backend_selection(get_cuda_device_name_key())
        except Exception as exc:
            return AttentionRuntime(
                flash_attn_fwd=_missing_runtime_fn("attention", "flash_attn_fwd", exc),
                block_bidirectional_mask=_missing_mask(_BLOCK_BIDIRECTIONAL_HASH),
                windowed_blockdiag_mask=_missing_mask(_WINDOWED_BLOCKDIAG_HASH),
            )

        try:
            from kestrel_kernels.flash_attn.cute.mask_definitions import (
                cute_block_bidirectional_mask,
                cute_windowed_blockdiag_mask,
            )
        except Exception:
            block_bidirectional_mask = _missing_mask(_BLOCK_BIDIRECTIONAL_HASH)
            windowed_blockdiag_mask = _missing_mask(_WINDOWED_BLOCKDIAG_HASH)
        else:
            block_bidirectional_mask = cute_block_bidirectional_mask
            windowed_blockdiag_mask = cute_windowed_blockdiag_mask

        return AttentionRuntime(
            flash_attn_fwd=_flash_attn_fwd,
            block_bidirectional_mask=block_bidirectional_mask,
            windowed_blockdiag_mask=windowed_blockdiag_mask,
        )

    @property
    def moe(self) -> MoeRuntime:
        try:
            from kestrel_kernels.topk import topk_fwd as cuda_topk_fwd
            from kestrel_kernels.moe.dispatch import (
                forward as moe_forward,
                prepare as moe_prepare,
            )
            from kestrel_kernels.moe import prepare_lora_metadata
        except Exception as exc:
            return MoeRuntime(
                prepare=_missing_runtime_fn("moe", "prepare", exc),
                forward=_missing_runtime_fn("moe", "forward", exc),
                topk_fwd=_missing_runtime_fn("moe", "topk_fwd", exc),
                prepare_lora_metadata=_missing_runtime_fn(
                    "moe", "prepare_lora_metadata", exc
                ),
                supports_lora=lambda *_args, **_kwargs: False,
            )

        return MoeRuntime(
            prepare=moe_prepare,
            forward=moe_forward,
            topk_fwd=_moe_topk_fwd(cuda_topk_fwd),
            prepare_lora_metadata=prepare_lora_metadata,
            supports_lora=_cuda_moe_supports_lora,
        )

    @property
    def cache(self) -> CacheRuntime:
        from kestrel_kernels.kv_cache_write_ops import reshape_and_cache_flash
        from kestrel_kernels.paged_kv_metadata_ops import build_paged_kv_metadata

        return CacheRuntime(
            reshape_and_cache_flash=reshape_and_cache_flash,
            build_paged_kv_metadata=build_paged_kv_metadata,
        )

    @property
    def rotary(self) -> RotaryRuntime:
        from kestrel_kernels.rotary_embedding_ops import (
            apply_neox_rotary,
            prepare_neox_rotary,
            rotary_embedding,
        )
        from kestrel_kernels.multiaxis_rotary import spatial_rope_apply, text_mrope_apply

        return RotaryRuntime(
            rotary_embedding=rotary_embedding,
            prepare_neox=prepare_neox_rotary,
            apply_neox=apply_neox_rotary,
            text_mrope_apply=text_mrope_apply,
            spatial_rope_apply=spatial_rope_apply,
        )

    @property
    def tau(self) -> TauRuntime:
        from kestrel_kernels.tau_tail_ops import tau_tail_apply_into

        return TauRuntime(tau_tail_apply_into=tau_tail_apply_into)

    @property
    def vision(self) -> VisionRuntime:
        from kestrel_kernels.fused_linear_residual_ops import (
            fused_linear_bias_residual_into,
        )

        return VisionRuntime(
            fused_linear_bias_residual_into=fused_linear_bias_residual_into
        )

    @property
    def linear(self) -> LinearRuntime:
        from kestrel_kernels.block_scaled_linear import block_scaled_linear
        from kestrel_kernels.linear_ops import linear

        return LinearRuntime(
            linear=linear,
            block_scaled_linear=block_scaled_linear,
        )

    @property
    def gelu(self) -> GeluRuntime:
        from kestrel_kernels.gelu_residual import gelu_cute

        return GeluRuntime(gelu_cute=gelu_cute)

    @property
    def gated_delta(self) -> GatedDeltaRuntime:
        from kestrel_kernels.gated_delta.workspace import (
            allocate_packed_gated_delta_prefill_workspace,
        )
        from kestrel_kernels.gated_delta import (
            bind_packed_prefill_topology,
            causal_conv1d_packed,
            causal_conv1d_update_indexed,
            gated_rmsnorm,
            materialize_replay_state_indexed,
            packed_gated_delta_rule_prefill,
            packed_prefill_prepare,
            packed_recurrent_gated_delta_rule_decode_replay_indexed,
            packed_recurrent_gated_delta_rule_decode_replay_indexed_gqa,
            packed_recurrent_gated_delta_rule_prefill,
            packed_recurrent_gated_delta_rule_verify_replay_indexed,
            supports_packed_gdn,
        )

        return GatedDeltaRuntime(
            allocate_packed_gated_delta_prefill_workspace=allocate_packed_gated_delta_prefill_workspace,
            bind_packed_prefill_topology=bind_packed_prefill_topology,
            causal_conv1d_packed=causal_conv1d_packed,
            causal_conv1d_update_indexed=causal_conv1d_update_indexed,
            gated_rmsnorm=gated_rmsnorm,
            materialize_replay_state_indexed=materialize_replay_state_indexed,
            packed_gated_delta_rule_prefill=packed_gated_delta_rule_prefill,
            packed_prefill_prepare=packed_prefill_prepare,
            packed_recurrent_gated_delta_rule_decode_replay_indexed=packed_recurrent_gated_delta_rule_decode_replay_indexed,
            packed_recurrent_gated_delta_rule_decode_replay_indexed_gqa=packed_recurrent_gated_delta_rule_decode_replay_indexed_gqa,
            packed_recurrent_gated_delta_rule_prefill=packed_recurrent_gated_delta_rule_prefill,
            packed_recurrent_gated_delta_rule_verify_replay_indexed=packed_recurrent_gated_delta_rule_verify_replay_indexed,
            supports_packed_gdn=supports_packed_gdn,
        )

    @property
    def dense(self) -> DenseRuntime:
        from kestrel_kernels.fused_mlp_ops import (
            fused_mlp_gelu_bias_residual_cuda,
            mlp_gelu_bias_residual,
        )
        from kestrel_kernels.layernorm_cuda_ops import (
            layernorm_bias,
            layernorm_bias_into,
        )
        from kestrel_kernels.rmsnorm import (
            add_rmsnorm,
            add_rmsnorm_into,
            rmsnorm,
            rmsnorm_into,
        )
        from kestrel_kernels.swiglu import gated_activation_into

        return DenseRuntime(
            fused_mlp_gelu_bias_residual=fused_mlp_gelu_bias_residual_cuda,
            mlp_gelu_bias_residual=mlp_gelu_bias_residual,
            layernorm_bias_into=layernorm_bias_into,
            layernorm_bias=layernorm_bias,
            rmsnorm_into=rmsnorm_into,
            rmsnorm=rmsnorm,
            add_rmsnorm_into=add_rmsnorm_into,
            add_rmsnorm=add_rmsnorm,
            gated_activation_into=gated_activation_into,
        )

    @property
    def sampling(self) -> SamplingRuntime:
        from kestrel_kernels.sampling import (
            apply_logits_constraints_,
            allocate_greedy_tail_workspace,
            constrained_argmax_from_logits,
            greedy_logprobs_from_logits,
            greedy_tail_from_logits,
            sample_step_from_logits,
        )

        return SamplingRuntime(
            sample_step_from_logits=sample_step_from_logits,
            greedy_logprobs_from_logits=greedy_logprobs_from_logits,
            apply_logits_constraints_=apply_logits_constraints_,
            constrained_argmax_from_logits=constrained_argmax_from_logits,
            greedy_tail_from_logits=greedy_tail_from_logits,
            allocate_greedy_tail_workspace=allocate_greedy_tail_workspace,
        )

    @property
    def compute_capability(self) -> tuple[int, int]:
        if not torch.cuda.is_available():
            return (0, 0)
        return torch.cuda.get_device_capability()

    @property
    def is_sm90(self) -> bool:
        major, _minor = self.compute_capability
        return major == 9


_RUNTIME: KernelRuntime | None = None


def get_runtime() -> KernelRuntime:
    global _RUNTIME
    if _RUNTIME is not None:
        return _RUNTIME
    if sys.platform == "darwin":
        # Deferred because MPSKernelRuntime's module imports this module —
        # breaking the circular import at function call time.
        from kestrel_kernels.mps.runtime import MPSKernelRuntime

        _RUNTIME = MPSKernelRuntime()
    else:
        _RUNTIME = KernelRuntime()
    return _RUNTIME


